package com.nextrade.engine.risk; public final class DailyLossRule implements RiskRule { private final com.nextrade.common.valueobject.Money limit; public DailyLossRule(com.nextrade.common.valueobject.Money limit){this.limit=limit;} public RiskDecision evaluate(RiskContext context){return context.dailyPnl().isNegative() && context.dailyPnl().abs().compareTo(limit)>0?RiskDecision.block("DAILY_LOSS","Daily loss limit exceeded"):RiskDecision.allow();} public String name(){return "DAILY_LOSS";} }